<?php if($s->enabled('resource_library')): $resourceOwner=$owner??$me;$releases=$a->resources->entries((int)$item['id'],$resourceOwner);if($releases): ?>
<section class="resource-library" aria-label="<?= t('Resource editions') ?>"><header class="resource-library-head"><span class="quick-icon"><?= icon('layers') ?></span><div><h2><?= t('Resource editions') ?></h2><p><?= t('Choose a release or mirror. Your existing content access applies to every edition.') ?></p></div></header>
<?php foreach($releases as $release): ?><article class="resource-release"><h3 class="resource-title"><?= e($release['label']) ?><?php if($release['release_version']!==''): ?><span class="pill soft"><?= e($release['release_version']) ?></span><?php endif ?><?php if(!(int)$release['active']): ?><span class="pill warning"><?= t('Disabled') ?></span><?php endif ?></h3>
<?php if($release['notes']!==''): ?><p class="resource-notes"><?= e($release['notes']) ?></p><?php endif ?>
<footer><span class="muted small"><?= t((int)$release['media_id']?'Private file':'External mirror') ?> · <?= dt((int)$release['updated_at'],'Y.m.d') ?></span><a class="btn small" href="<?= e(url('resource',['id'=>(int)$release['id']])) ?>"><?= icon('download') ?><?= t('Get this edition') ?></a></footer>
<?php if($me && $s->enabled('resource_reports')): ?><details><summary><?= t('Report an unavailable resource') ?></summary><?= form_start('resource_report').hidden('resource_id',$release['id']) ?><?php select_field('reason','Issue type',array_map('tr',['unavailable'=>'Link unavailable','outdated'=>'Outdated version','incorrect'=>'Incorrect file','other'=>'Other']),'unavailable');field('body','Details','','textarea',['maxlength'=>'2000']);button('Send report','secondary small','flag'); ?></form></details><?php endif ?>
</article><?php endforeach ?></section><?php endif;endif ?>
